    let driving=false,pos=new THREE.Vector3(-58,0,23),yaw=Math.PI/2,velocity=new THREE.Vector3(),inside=false;
    const prompt=document.querySelector('#prompt'),chat=document.querySelector('#chat');
    function toggleDrive(){if(!driving&&car.position.distanceTo(pos)<11){driving=true;chat.innerHTML='<div class="line">Vehicle entered</div>';prompt.style.display='none'}else if(driving){driving=false;pos.copy(car.position).add(new THREE.Vector3(Math.cos(yaw)*6,0,Math.sin(yaw)*6));chat.innerHTML='<div class="line">Vehicle exited</div>'}}
    // world boundary physics
    const obstacles=[];
    function safe(p){return p.x>-105&&p.x<105&&p.z>-105&&p.z<105}

    let clock=new THREE.Clock(),cash=0;
    function animate(){requestAnimationRect;const dt=Math.min(clock.getDelta(),.05);const forward=keys.w||keys.arrowup||touch.w,back=keys.s||keys.arrowdown||touch.s,left=keys.a||keys.arrowleft||touch.a,right=keys.d||keys.arrowright||touch.d;
      if(driving){const acc=(forward?17:0)-(back?12:0);car.userData.speed*=Math.pow(.08,dt);car.userData.speed+=acc*dt;car.userData.speed=Math.max(-8,Math.min(22,car.userData.speed));const steer=(right?1:0)-(left?1:0);car.rotation.y-=steer*dt*1.5*(.35+Math.abs(car.userData.speed)/20);const dir=new THREE.Vector3(-Math.sin(car.rotation.y),0,-Math.cos(car.rotation.y));const next=car.position.clone().addScaledVector(dir,car.userData.speed*dt);if(safe(next))car.position.copy(next);else car.userData.speed*=-.25;
        pos.copy(car.position);yaw=car.rotation.y; }
      else{const vyaw=camera.rotation.y;const dx=(right?1:0)-(left?1:0),dz=(forward?1:0)-(back?1:0);if(dx||dz){const len=Math.hypot(dx,dz);velocity.set(dx/len,0,dz/len);velocity.applyAxisAngle(new THREE.Vector3(0,1,0),-yaw);if(!safe(pos.clone().addScaledVector(velocity,dt*9))){}else pos.addScaledVector(velocity,dt*9)}}
      // camera follow orbit
      let target,dist;if(driving){target=car.position;dist=19}else{target=pos;dist=12}
      const desired=new THREE.Vector3(target.x-Math.sin(yaw)*dist,driving?10:9,target.z-Math.cos(yaw)*dist);camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(target.x,driving?2:3,target.z);
      if(!driving){prompt.style.display=car.position.distanceTo(pos)<11?'block':'none';prompt.textContent='Press E — Drive'}
      if(driving){cash+=Math.abs(car.userData.speed)*dt*.2;if(cash>999999)cash=999999;document.querySelector('#cash').textContent='B$ '+Math.floor(cash)}
      renderer.render(scene,camera);requestAnimationFrame(animate)}

    // initial camera
    pos.set(-58,0,23);camera.position.set(-70,9,20);camera.lookAt(pos);requestAnimationFrame(animate);
  </script>

</body></html>

